fn expanded_macos_path(path string) string {
	mut expanded := path
	if path == '~' {
		expanded = os.home_dir()
	} else if path.starts_with('~/') {
		expanded = os.join_path(os.home_dir(), path[2..])
	}
	return os.norm_path(os.abs_path(expanded))
}

pub fn macos_system_dir(path string) bool {
	return expanded_macos_path(path) in macos_system_directories.split('|')
}

pub fn macos_undeletable(path string) bool {
	expanded := expanded_macos_path(path)
	if expanded in macos_system_directories.split('|') {
		return true
	}
	return macos_user_undeletable_directories.split('|').any(expanded_macos_path(it) == expanded)
}

