	if args.len == 0 {
		panic('MacOS.system_dir? requires a path')
	}
	return brew_runtime.bool_value(macos_system_dir(args[0].as_string()))
}

// Ruby method `self.undeletable?(path)` at line 387.
pub fn ruby_macos_l387_d2_self_undeletable(args ...brew_runtime.Value) brew_runtime.Value {
	if args.len == 0 {
		panic('MacOS.undeletable? requires a path')
	}
	return brew_runtime.bool_value(macos_undeletable(args[0].as_string()))
}

